arguments.file_text:
@page "/settings"
@using sv_38984a9c6c54418485cd10938ab31d7b.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

/* Settings Dashboard Layout */
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    max-width: 1200px;
    margin: 0 auto;
    gap: 0;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    overflow: hidden;
    background: #fff;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    background: #f8fafc;
    border-right: 1px solid #e2e8f0;
    padding: 1rem 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    font-size: 0.95rem;
    color: #475569;
    transition: background 0.15s, color 0.15s;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e2e8f0;
    color: #1e293b;
}

.settings-sidebar li.active {
    background: #e0e7ff;
    color: #3730a3;
    border-left-color: #4f46e5;
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.1rem;
}

/* Main Content */
.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #1e293b;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    color: #334155;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #374151;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.9rem;
    transition: border-color 0.15s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #4f46e5;
    box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.form-group textarea {
    resize: vertical;
}

/* Buttons */
.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background: #4f46e5;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: background 0.15s;
}

.btn-primary:hover {
    background: #4338ca;
}

.btn-secondary {
    padding: 0.5rem 1.25rem;
    background: #f1f5f9;
    color: #475569;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: background 0.15s;
}

.btn-secondary:hover {
    background: #e2e8f0;
}

.btn-danger {
    padding: 0.5rem 1.25rem;
    background: #dc2626;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

.btn-danger:hover {
    background: #b91c1c;
}

.btn-small {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    animation: fadeIn 0.3s ease;
}

.toast.success {
    background: #d1fae5;
    color: #065f46;
    border: 1px solid #6ee7b7;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Profile Section */
.profile-avatar {
    margin-bottom: 1.5rem;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #e2e8f0;
}

.avatar-url {
    margin-top: 0.5rem;
    font-size: 0.8rem;
    color: #64748b;
    word-break: break-all;
}

/* Toggle Items */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.toggle-item input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
    accent-color: #4f46e5;
}

/* Channel List */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding-left: 0.25rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.9rem;
    cursor: pointer;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid #e2e8f0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #f8fafc;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
    color: #1e293b;
    border-radius: 6px;
}

.panel-header:hover {
    background: #f1f5f9;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e2e8f0;
}

/* Status Indicators */
.status-row {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.status-indicator {
    font-size: 0.9rem;
    font-weight: 500;
}

.status-indicator.enabled {
    color: #059669;
}

.status-indicator.disabled {
    color: #6b7280;
}

.info-text {
    font-size: 0.85rem;
    color: #64748b;
    margin-top: 0.5rem;
}

.error-message {
    color: #dc2626;
    font-size: 0.85rem;
    margin: 0.5rem 0;
}

.success-message {
    color: #059669;
    font-size: 0.85rem;
    margin: 0.5rem 0;
}

/* Sessions Table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e2e8f0;
}

.sessions-table th {
    background: #f8fafc;
    font-weight: 600;
    color: #475569;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.025em;
}

.current-badge {
    font-size: 0.8rem;
    color: #4f46e5;
    font-weight: 500;
}

/* Confirmation Dialog */
.dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: #fff;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
}

.dialog h4 {
    margin: 0 0 0.75rem;
    color: #1e293b;
}

.dialog p {
    color: #475569;
    font-size: 0.9rem;
    margin-bottom: 1.25rem;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

/* Appearance Preview */
.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.radio-item input[type="radio"] {
    accent-color: #4f46e5;
}

.appearance-preview {
    margin-top: 1.5rem;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    overflow: hidden;
    max-width: 500px;
}

.preview-header {
    padding: 0.5rem 1rem;
    font-weight: 600;
    font-size: 0.85rem;
    background: #f8fafc;
    border-bottom: 1px solid #e2e8f0;
    color: #475569;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.preview-body {
    padding: 1.25rem;
}

.preview-text {
    margin: 0 0 1rem;
    color: #334155;
}

.preview-button {
    padding: 0.4rem 1rem;
    border-radius: 4px;
    border: 1px solid #d1d5db;
    background: #f9fafb;
    cursor: default;
    font-size: 0.85rem;
}

/* Preview Themes */
.preview-theme-dark {
    background: #1e293b;
}

.preview-theme-dark .preview-header {
    background: #334155;
    color: #e2e8f0;
    border-color: #475569;
}

.preview-theme-dark .preview-body {
    color: #e2e8f0;
}

.preview-theme-dark .preview-text {
    color: #cbd5e1;
}

.preview-theme-dark .preview-button {
    background: #475569;
    color: #e2e8f0;
    border-color: #64748b;
}

.preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e293b 50%);
}

/* Preview Font Sizes */
.preview-font-small .preview-body {
    font-size: 0.8rem;
}

.preview-font-medium .preview-body {
    font-size: 0.95rem;
}

.preview-font-large .preview-body {
    font-size: 1.15rem;
}

/* Preview Compact Mode */
.preview-compact .preview-body {
    padding: 0.5rem 1rem;
    line-height: 1.3;
}

.preview-compact .preview-header {
    padding: 0.3rem 1rem;
}

